export type SqlColumnType = "text" | "number" | "boolean" | "date" | "json"

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

/** One value as a driver returns it. `null` and `undefined` both render as NULL. */
export type SqlValue = string | number | bigint | boolean | Date | null | undefined | object

export interface SqlColumn {
  name: string
  /** Inferred from the values when omitted: numbers align to the end in tabular figures. */
  type?: SqlColumnType
  /** Custom cell content. Return a string to keep truncation and the full value popover. */
  format?: (value: SqlValue) => React.ReactNode
}

/** A row as an array in column order, or an object keyed by column name. */
export type SqlRow = SqlValue[] | Record<string, SqlValue>

const CSV_SPECIAL = /[",\r\n]|^\s|\s$/

function isNull(value: SqlValue): value is null | undefined {
  return value === null || value === undefined
}

/** Plain text for a value: what CSV, copy and the popover use. NULL is an empty string. */
function valueText(value: SqlValue, pretty = false): string {
  if (isNull(value)) return ""
  if (value instanceof Date) return value.toISOString()
  if (typeof value === "object") {
    try {
      return JSON.stringify(value, null, pretty ? 2 : undefined) ?? ""
    } catch {
      return String(value)
    }
  }
  return String(value)
}

function cellAt(row: SqlRow, index: number, name: string): SqlValue {
  return Array.isArray(row) ? row[index] : (row as Record<string, SqlValue>)[name]
}

/**
 * Serializes a result as RFC 4180 CSV: fields with commas, quotes, line breaks or edge spaces are
 * quoted, quotes are doubled, NULL becomes an empty field and lines end with CRLF.
 */
export function sqlResultToCsv(
  columns: ReadonlyArray<SqlColumn | string>,
  rows: ReadonlyArray<SqlRow>,
): string {
  const cols = columns.map((c) => (typeof c === "string" ? c : c.name))
  const field = (text: string) => (CSV_SPECIAL.test(text) ? `"${text.replace(/"/g, '""')}"` : text)
  const lines = [cols.map(field).join(",")]
  for (const row of rows) {
    lines.push(cols.map((name, i) => field(valueText(cellAt(row, i, name)))).join(","))
  }
  return lines.join("\r\n")
}

export type SqlResultState = "running" | "done" | "error" | "canceled"

export interface SqlResultError {
  /** The database message without the severity, for example `column "plan_tier" does not exist`. */
  message: string
  /** 1-based character offset into the query, as Postgres reports it. Draws a caret there. */
  position?: number
  /** Severity shown before the message. Defaults to `ERROR`. */
  severity?: string
  detail?: string
  /** How to fix it. Shown after the message. */
  hint?: string
  /** SQLSTATE or driver code, for example `42703`. */
  code?: string
}

export interface SqlResultProps extends Omit<React.ComponentProps<"div">, "children" | "onError"> {
  query: string
  state?: SqlResultState
  /** Database or connection name, shown in the header. */
  database?: string
  /** Column names or definitions. Taken from the first object row when omitted. */
  columns?: ReadonlyArray<SqlColumn | string>
  rows?: ReadonlyArray<SqlRow>
  /** Total rows the query returned, when more exist than `rows` holds. */
  rowCount?: number
  /** Run time in ms once finished. */
  durationMs?: number
  /** Epoch ms when the query started. Drives the live timer while running. */
  startedAt?: number
  error?: SqlResultError | string
  /** 1-based page. Paging controls show when `page`, `pageSize` and `onPageChange` are set. */
  page?: number
  pageSize?: number
  onPageChange?: (page: number) => void
  /** Height of the result scroll area. Number means px. Default 360. */
  maxHeight?: number | string
  /** Queries longer than this many lines collapse behind Show full query. `false` turns it off. Default 6. */
  collapseAfter?: number | false
  /** Text longer than this truncates and opens its full value in a popover. Default 48. */
  truncateAfter?: number
  /** Row numbers in a gutter. Default true. */
  showRowNumbers?: boolean
  /** File name for Download CSV. Default `query-result.csv`. */
  exportFilename?: string
  /** Replaces the built-in download, for example to export every row from your server. */
  onDownload?: () => void
  /** Hide Copy as CSV and Download CSV. */
  hideExport?: boolean
  /** Shows Retry query on errors and Run again after a cancel. */
  onRetry?: () => void
  /** Shows Cancel query while running. */
  onCancel?: () => void
  /** `plain` sits inside a surface you already have. */
  variant?: "card" | "plain"
}

interface UseChatcnElapsedOptions {
  /** True while the timed work is happening. */
  running: boolean
  /** Epoch ms when the work started. Measured from the first `running` render when omitted. */
  startedAt?: number
  /** Final duration from the runtime. Wins over the measured one once `running` is false. */
  durationMs?: number
}

interface UseChatcnElapsedResult {
  /** Live elapsed ms while running, the final duration afterwards, `undefined` when unknown. */
  ms: number | undefined
  running: boolean
}

/**
 * Elapsed time for a step, a run or a reasoning block.
 *
 * Ticks once per second, aligned to the start time so the counter turns over exactly at 1 s,
 * 2 s and so on, never at random offsets. A counter that changes faster only adds noise.
 */
function useChatcnElapsed({
  running,
  startedAt,
  durationMs,
}: UseChatcnElapsedOptions): UseChatcnElapsedResult {
  const [autoStart, setAutoStart] = React.useState<number>()
  const [measured, setMeasured] = React.useState<number>()
  // Starts empty and reads the clock after mount: a render must not read it (Next.js prerender).
  const [now, setNow] = React.useState<number | null>(null)
  const start = startedAt ?? autoStart

  // Record our own start when the caller gives none. A new run (running again) starts over.
  React.useEffect(() => {
    if (!running) return
    if (startedAt === undefined) setAutoStart((prev) => prev ?? Date.now())
    setMeasured(undefined)
    setNow(Date.now())
  }, [running, startedAt])

  // Freeze the measured duration when the work stops.
  const wasRunning = React.useRef(running)
  React.useEffect(() => {
    if (wasRunning.current && !running && start !== undefined) {
      setMeasured(Date.now() - start)
      setAutoStart(undefined)
    }
    wasRunning.current = running
  }, [running, start])

  React.useEffect(() => {
    if (!running || start === undefined) return
    let id: number
    const schedule = () => {
      const elapsed = Date.now() - start
      // Next whole-second boundary, plus a few ms so rounding never shows the old second.
      const wait = 1000 - (((elapsed % 1000) + 1000) % 1000) + 8
      id = window.setTimeout(() => {
        setNow(Date.now())
        schedule()
      }, wait)
    }
    schedule()
    return () => window.clearTimeout(id)
  }, [running, start])

  if (running)
    return { ms: start === undefined ? undefined : Math.max(0, (now ?? start) - start), running }
  return { ms: durationMs ?? measured, running }
}

function inferType(rows: ReadonlyArray<SqlRow>, index: number, name: string): SqlColumnType {
  let type: SqlColumnType | undefined
  for (const row of rows) {
    const value = cellAt(row, index, name)
    if (isNull(value)) continue
    const next: SqlColumnType =
      typeof value === "number" || typeof value === "bigint"
        ? "number"
        : typeof value === "boolean"
          ? "boolean"
          : value instanceof Date
            ? "date"
            : typeof value === "object"
              ? "json"
              : "text"
    if (type && type !== next) return "text"
    type = next
  }
  return type ?? "text"
}

function normalizeColumns(
  columns: SqlResultProps["columns"],
  rows: ReadonlyArray<SqlRow>,
): SqlColumn[] {
  const list: SqlColumn[] = columns
    ? columns.map((c) => (typeof c === "string" ? { name: c } : c))
    : (() => {
        const first = rows[0]
        if (!first) return []
        if (Array.isArray(first)) return first.map((_, i) => ({ name: `column_${i + 1}` }))
        return Object.keys(first).map((name) => ({ name }))
      })()
  return list.map((column, index) =>
    column.type ? column : { ...column, type: inferType(rows, index, column.name) },
  )
}

interface ErrorLocation {
  line: number
  column: number
  /** Characters to underline: the identifier or quoted name at the position. */
  length: number
}

/** Line and column (both 1-based) of a 1-based character offset, and the token it points at. */
function locate(query: string, position: number): ErrorLocation {
  const index = Math.max(0, position - 1)
  const before = query.slice(0, index)
  const line = before.split("\n").length
  const column = before.length - before.lastIndexOf("\n")
  const token = /^(?:"[^"\n]*"|[\w$.]+)/.exec(query.slice(index))
  return { line, column, length: Math.max(1, token?.[0].length ?? 1) }
}

const NBSP2 = " "

/**
 * Formats a duration the chatcn way: numerals, a non-breaking space before the unit.
 * `precise` (the default) keeps a decimal under 10 s and milliseconds under 1 s, for finished
 * steps. Turn it off for live counters and "Thought for 12 s", which read in whole seconds.
 */
function formatChatcnDuration(ms: number, { precise = true }: { precise?: boolean } = {}) {
  const safe = Math.max(0, ms)
  if (precise && safe < 1000) return `${Math.max(1, Math.round(safe))}${NBSP2}ms`
  const s = safe / 1000
  if (precise && s < 10) return `${s.toFixed(1)}${NBSP2}s`
  if (s < 60) return `${precise ? Math.round(s) : Math.floor(s)}${NBSP2}s`
  const totalS = Math.floor(s)
  const h = Math.floor(totalS / 3600)
  const m = Math.floor((totalS % 3600) / 60)
  const rest = totalS % 60
  if (h > 0) return `${h}${NBSP2}h ${m}${NBSP2}m`
  return `${m}${NBSP2}m ${rest}${NBSP2}s`
}

/**
 * The only shimmer in chatcn: a status label such as "Thinking". Static under reduced motion.
 * Pass `active={false}` to settle it into plain subtle text.
 */
function ShimmerText({
  active = true,
  className,
  ...props
}: React.ComponentProps<"span"> & { active?: boolean }) {
  return (
    <span
      data-slot="shimmer-text"
      className={cn("font-medium", active ? "chatcn-shimmer" : "text-(color:--chatcn-fg-subtle)", className)}
      {...props}
    />
  )
}

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

const NBSP = " "

function plural(n: number, word: string) {
  return `${n.toLocaleString("en-US")}${NBSP}${n === 1 ? word : `${word}s`}`
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

