/* -------------------------------------------------------------------------------------------------
 * Status glyph
 * -----------------------------------------------------------------------------------------------*/

function SqlResultGlyph({ state }: { state: SqlResultState }) {
  let glyph: React.ReactNode = <CircleCheckIcon />
  let tone = "text-(color:--chatcn-green)"
  if (state === "running") {
    glyph = <Spinner />
    tone = "text-(color:--chatcn-blue)"
  } else if (state === "error") {
    glyph = <CircleXIcon />
    tone = "text-(color:--chatcn-red)"
  } else if (state === "canceled") {
    glyph = <CircleStopIcon />
    tone = "text-(color:--chatcn-fg-subtle)"
  }
  return (
    <span
      data-slot="sql-result-status"
      className={cn("grid size-4 shrink-0 place-items-center [&_svg]:size-4", tone)}
    >
      <span
        key={state}
        className="grid place-items-center motion-safe:animate-[chatcn-swap_150ms_var(--chatcn-ease-out)]"
      >
        {glyph}
      </span>
    </span>
  )
}

