          // biome-ignore lint/a11y/noNoninteractiveTabindex: scrollable regions must be reachable by keyboard
          tabIndex={0}
          className={cn(
            "chatcn-scroll text-[0.75rem]/[1rem] overflow-x-auto py-2.5 ps-3.5 pe-10 font-mono leading-5 whitespace-pre outline-none",
            "focus-visible:shadow-[inset_0_0_0_2px_var(--chatcn-accent)]",
            collapsed && "[mask-image:linear-gradient(to_bottom,black_55%,transparent)]",
          )}
        >
          <code className="flex w-max min-w-full flex-col">
            {lines.slice(0, shownCount).map((tokens, i) => {
              const number = i + 1
              return (
                <React.Fragment key={i}>
                  <span className="min-h-5">
                    {errorAt && errorAt.line === number
                      ? markRange(tokens, errorAt.column - 1, errorAt.column - 1 + errorAt.length)
                      : tokens.map((token, t) => (
                          <span key={t} className={chatcnTokenClass[token.role]}>
                            {token.content}
                          </span>
                        ))}
                  </span>
                  {errorAt && errorAt.line === number ? (
                    <span
                      data-slot="sql-result-caret"
                      aria-hidden="true"
                      className="text-(color:--chatcn-red) min-h-5 font-medium select-none"
                    >
                      {" ".repeat(Math.max(0, errorAt.column - 1))}^
                    </span>
                  ) : null}
                </React.Fragment>
              )
            })}
          </code>
        </pre>
      </section>
      <CopyButton
        size="icon-xs"
        value={source}
        label="Copy query"
        className="text-(color:--chatcn-fg-subtle) bg-(color:--chatcn-inset) absolute end-2 top-2 pointer-coarse:size-11"
      />
      {collapsible ? (
        <div className={cn("flex ps-1.5 pb-1.5", collapsed && "-mt-2")}>
          <Button
            size="xs"
            aria-expanded={!collapsed}
            aria-controls={id}
            onClick={() => setExpanded((v) => !v)}
            className="text-(color:--chatcn-fg-muted) pointer-coarse:h-11"
          >
            {collapsed ? (
              <>
                Show full query
                <span className="text-(color:--chatcn-fg-subtle) font-normal tabular-nums">
                  {plural(lines.length, "line")}
                </span>
                <ChevronDownIcon />
              </>
            ) : (
              <>
                Show less
                <ChevronUpIcon />
              </>
            )}
          </Button>
        </div>
      ) : null}
    </div>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Cells
 * -----------------------------------------------------------------------------------------------*/

function NullBadge() {
  return (
    <span className="rounded-(--chatcn-radius-xs) bg-(color:--chatcn-fill) text-(color:--chatcn-fg-subtle) text-[0.75rem]/[1rem] px-1 font-mono">
      <span aria-hidden="true">NULL</span>
      <span className="sr-only">null</span>
    </span>
  )
}

const numberFormat = new Intl.NumberFormat("en-US", { maximumFractionDigits: 6 })

/* -------------------------------------------------------------------------------------------------
 * Parts
 * -----------------------------------------------------------------------------------------------*/

/**
 * Root. Controlled with `open` and `onOpenChange`, or uncontrolled with `defaultOpen`.
 * Not modal by default: the page stays scrollable and clickable.
 */
function Popover(props: PopoverPrimitive.Root.Props) {
  return <PopoverPrimitive.Root {...props} />
}

/** The button that toggles the popover. Pass `render={<Button />}` to use your own element. */
function PopoverTrigger(props: PopoverPrimitive.Trigger.Props) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />
}

interface PopoverContentProps extends PopoverPrimitive.Popup.Props {
  /** Side of the trigger to open on. Flips when there is no room. Default `bottom`. */
  side?: PopoverPrimitive.Positioner.Props["side"]
  /** Alignment along that side. Default `center`. */
  align?: PopoverPrimitive.Positioner.Props["align"]
  /** Gap to the trigger in px. Default 6. */
  sideOffset?: PopoverPrimitive.Positioner.Props["sideOffset"]
  alignOffset?: PopoverPrimitive.Positioner.Props["alignOffset"]
  /** Element to position against instead of the trigger. */
  anchor?: PopoverPrimitive.Positioner.Props["anchor"]
  /** Portal container. Defaults to `document.body`. */
  container?: PopoverPrimitive.Portal.Props["container"]
}

/** Surface shared by popovers and menus: 12 px radius, surface fill, medium shadow. */
const popupSurface = cn(
  "bg-(color:--chatcn-surface) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-md) rounded-(--chatcn-radius-lg) outline-none",
  "max-h-(--available-height) max-w-(--available-width)",
  // Shadows vanish in forced colors; keep an edge.
  "forced-colors:outline-1 forced-colors:outline-solid",
)

/* -------------------------------------------------------------------------------------------------
 * Motion
 *
 * Enter: opacity, scale from 0.96 and 4 px of travel away from the trigger, 180 ms ease-(--chatcn-ease-out),
 * growing out of the trigger through `--transform-origin`. Exit: 140 ms to scale 0.98, no travel.
 * Opened or dismissed with the keyboard, Base UI sets `data-instant` and nothing animates.
 * Reduced motion keeps the fade and drops scale and travel.
 * -----------------------------------------------------------------------------------------------*/

const popupMotion = cn(
  "ease-(--chatcn-ease-out) origin-(--transform-origin) transition-[opacity,scale,translate] duration-180",
  "data-[starting-style]:scale-96 data-[starting-style]:opacity-0",
  "data-[side=bottom]:data-[starting-style]:-translate-y-1 data-[side=top]:data-[starting-style]:translate-y-1",
  "data-[side=left]:data-[starting-style]:translate-x-1 data-[side=right]:data-[starting-style]:-translate-x-1",
  "data-[side=inline-end]:data-[starting-style]:-translate-x-1 data-[side=inline-start]:data-[starting-style]:translate-x-1",
  "data-[ending-style]:scale-98 data-[ending-style]:opacity-0 data-[ending-style]:duration-140",
  "data-[instant]:transition-none",
  "motion-reduce:translate-none! motion-reduce:scale-none!",
)

/**
 * The floating panel. Portalled and positioned for you. Padding defaults to 4 px, the right inset
 * for lists; pass `className="p-3"` for text content.
 */
function PopoverContent({
  side = "bottom",
  align = "center",
  sideOffset = 6,
  alignOffset = 0,
  anchor,
  container,
  className,
  ...props
}: PopoverContentProps) {
  return (
    <PopoverPrimitive.Portal container={container}>
      <PopoverPrimitive.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        alignOffset={alignOffset}
        anchor={anchor}
        className="z-50 outline-none"
      >
        <PopoverPrimitive.Popup
          data-slot="popover-content"
          className={cn(
            popupSurface,
            popupMotion,
            "text-[0.875rem]/[1.25rem] tracking-[-0.003em] chatcn-scroll overflow-auto p-1",
            className,
          )}
          {...props}
        />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  )
}

function FullValue({
  column,
  text,
  pretty,
  children,
}: {
  column: SqlColumn
  text: string
  pretty: string
  children: React.ReactNode
}) {
  const mono = column.type === "json"
  return (
    <Popover>
      <PopoverTrigger
        data-slot="sql-result-cell-trigger"
        // The visible value leads the name (the full text, which the cell truncates visually).
        aria-label={`${text}, ${column.name}. Show full value`}
        className={cn(
          "chatcn-focus rounded-(--chatcn-radius-xs) -mx-1 block w-full min-w-48 truncate px-1 text-start outline-none",
          "decoration-(color:--chatcn-border-strong) ease-(--chatcn-ease-standard) transition-colors duration-150",
          "hover:bg-(color:--chatcn-fill-hover) data-[popup-open]:bg-(color:--chatcn-fill-active)",
        )}
      >
        {children}
      </PopoverTrigger>
      <PopoverContent
        aria-label={`${column.name}, full value`}
        side="bottom"
        align="start"
        className="flex w-96 flex-col p-0"
      >
        <div className="flex h-9 shrink-0 items-center gap-2 ps-3 pe-1.5">
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-muted) min-w-0 flex-1 truncate font-mono">
            {column.name}
          </span>
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
            {plural(text.length, "character")}
          </span>
          <CopyButton size="icon-xs" value={pretty} label="Copy value" />
        </div>
        <div
          className={cn(
            "chatcn-scroll max-h-64 overflow-auto px-3 pb-3 [overflow-wrap:anywhere] whitespace-pre-wrap",
            mono ? "text-[0.75rem]/[1rem] font-mono leading-5" : "text-[0.8125rem]/[1.25rem] text-pretty",
          )}
        >
          {pretty}
        </div>
      </PopoverContent>
    </Popover>
  )
}

function SqlCell({
  value,
  column,
  truncateAfter,
}: {
  value: SqlValue
  column: SqlColumn
  truncateAfter: number
}) {
  if (isNull(value)) return <NullBadge />
  const custom = column.format?.(value)
  if (custom !== undefined && typeof custom !== "string") return <>{custom}</>
  if (custom === undefined && (typeof value === "number" || typeof value === "bigint")) {
    return <>{numberFormat.format(value)}</>
  }
  if (custom === undefined && typeof value === "boolean") {
    return <span className="text-(color:--chatcn-fg-muted) font-mono">{String(value)}</span>
  }
  const text = typeof custom === "string" ? custom : valueText(value)
  const long = text.length > truncateAfter || text.includes("\n")
  if (!long) return <>{text}</>
  const firstLine = text.split("\n")[0] ?? ""
  return (
    <FullValue
      column={column}
      text={text}
      pretty={typeof custom === "string" ? custom : valueText(value, true)}
    >
      {firstLine}
    </FullValue>
  )
}

const iconNode10: IconNode = [
