]

const ChevronLeftIcon: Icon = /* @__PURE__ */ createIcon("chevron-left", iconNode10)

const iconNode11: IconNode = [
  ["path", {"d":"m9.25 18 4.23-4.23a2.5 2.5 0 0 0 0-3.54L9.25 6"}],
]

const ChevronRightIcon: Icon = /* @__PURE__ */ createIcon("chevron-right", iconNode11)

const iconNode12: IconNode = [
  ["path", {"d":"M5.49 17.46A8.5 8.5 0 1 0 6.54 5.49"}],
  ["path", {"d":"m8.21 8.65-2.94-.26a2 2 0 0 1-1.82-2.16l.26-2.94"}],
]

const RotateCcwIcon: Icon = /* @__PURE__ */ createIcon("rotate-ccw", iconNode12)

/* -------------------------------------------------------------------------------------------------
 * SqlResult
 * -----------------------------------------------------------------------------------------------*/

/**
 * A SQL query the agent ran and what came back: the highlighted query, row count and run time,
 * a result table with a sticky header, NULL badges and full values for long cells, paging, CSV
 * export, and the running, empty, error and canceled states.
 */
export function SqlResult({
  query,
  state = "done",
  database,
  columns: columnsProp,
  rows = [],
  rowCount,
  durationMs,
  startedAt,
  error,
  page,
  pageSize,
  onPageChange,
  maxHeight = 360,
  collapseAfter = 6,
  truncateAfter = 48,
  showRowNumbers = true,
  exportFilename = "query-result.csv",
  onDownload,
  hideExport = false,
  onRetry,
  onCancel,
  variant = "card",
  className,
  ...props
}: SqlResultProps) {
  const running = state === "running"
  const elapsed = useChatcnElapsed({ running, startedAt, durationMs })
  const columns = React.useMemo(() => normalizeColumns(columnsProp, rows), [columnsProp, rows])
  // Columns with long text take the leftover width and truncate, so the rest never scrolls away.
  const wide = React.useMemo(() => {
    const set = new Set<number>()
    columns.forEach((column, c) => {
      if (column.type === "number" || column.type === "boolean") return
      for (const row of rows) {
        const value = cellAt(row, c, column.name)
        if (isNull(value)) continue
        const custom = column.format?.(value)
        const text =
          typeof custom === "string" ? custom : custom === undefined ? valueText(value) : ""
        if (text.length > truncateAfter || text.includes("\n")) {
          set.add(c)
          return
        }
      }
    })
    return set
  }, [columns, rows, truncateAfter])
  const err: SqlResultError | undefined =
    typeof error === "string" ? { message: error } : (error ?? undefined)
  const errorAt =
    state === "error" && err?.position !== undefined ? locate(query, err.position) : undefined

  const total = rowCount ?? rows.length
  const paged = page !== undefined && pageSize !== undefined && onPageChange !== undefined
  const pageCount = paged ? Math.max(1, Math.ceil(total / pageSize)) : 1
  const offset = paged ? (page - 1) * pageSize : 0
  const hasRows = state !== "error" && rows.length > 0
  const empty = state === "done" && rows.length === 0
  const truncated = !paged && hasRows && total > rows.length
  const canExport = !hideExport && hasRows && !running

  const csv = () => sqlResultToCsv(columns, rows)
  const timeText =
    elapsed.ms !== undefined ? formatChatcnDuration(elapsed.ms, { precise: !running }) : undefined

  const title =
    state === "running" ? (
      <ShimmerText>Running query</ShimmerText>
    ) : state === "error" ? (
      "Query failed"
    ) : state === "canceled" ? (
      "Query canceled"
    ) : (
      "Ran query"
    )

  const meta = [state === "done" ? plural(total, "row") : null, timeText ?? null].filter(
    Boolean,
  ) as string[]

  const announcement =
    state === "done"
      ? `Query returned ${plural(total, "row")}`
      : state === "error"
        ? `Query failed: ${err?.message ?? "the database returned an error"}`
        : state === "canceled"
          ? "Query canceled"
          : ""

  const footer =
    (paged && hasRows) ||
    truncated ||
    (state === "error" && onRetry) ||
    (state === "canceled" && onRetry) ||
    (running && onCancel)

  return (
    <div
      data-slot="sql-result"
      data-sql-result-state={state}
      data-variant={variant}
      aria-busy={running || undefined}
      className={cn(
        "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) flex min-w-0 flex-col",
        variant === "card" &&
          "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) overflow-hidden forced-colors:outline-1 forced-colors:outline-solid",
        className,
      )}
      {...props}
    >
      <div className="flex h-10 min-w-0 items-center gap-2.5 ps-3.5 pe-2 pointer-coarse:h-11">
        <SqlResultGlyph state={state} />
        <span className="flex min-w-0 flex-1 items-baseline gap-2">
          <span className={cn("shrink-0 font-medium", state === "error" && "text-(color:--chatcn-red)")}>
            {title}
          </span>
          {database ? (
            <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex min-w-0 items-center gap-1 self-center font-mono">
              <DatabaseIcon aria-hidden="true" className="size-3.5 shrink-0" />
              <span className="truncate">{database}</span>
            </span>
          ) : null}
        </span>
        {meta.length > 0 ? (
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
            {meta.map((part, i) => (
              <React.Fragment key={part}>
                {i > 0 ? " · " : null}
                <bdi>{part}</bdi>
              </React.Fragment>
            ))}
          </span>
        ) : null}
        {canExport ? (
          <span className="-me-0.5 flex shrink-0 items-center gap-0.5">
            <Tooltip content="Copy as CSV">
              <CopyButton value={csv} label="Copy as CSV" className="pointer-coarse:size-11" />
            </Tooltip>
            <Tooltip content="Download CSV">
              <Button
                size="icon-sm"
                aria-label="Download CSV"
                className="pointer-coarse:size-11"
                onClick={() => (onDownload ? onDownload() : downloadCsv(csv(), exportFilename))}
              >
                <DownloadIcon />
              </Button>
            </Tooltip>
          </span>
        ) : null}
      </div>

      <SqlQuery query={query} collapseAfter={collapseAfter} errorAt={errorAt} />

      {state === "error" ? (
        <div data-slot="sql-result-error" className="flex flex-col gap-1 px-3.5 py-3">
          <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) font-mono [overflow-wrap:anywhere]">
            <span className="text-(color:--chatcn-red) font-medium">{err?.severity ?? "ERROR"}:</span>{" "}
            {err?.message ?? "The database returned an error without a message."}
          </p>
          {errorAt || err?.code ? (
            <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) tabular-nums">
              {[
                errorAt ? `Line ${errorAt.line}, column ${errorAt.column}` : null,
                err?.code ? `SQLSTATE ${err.code}` : null,
              ]
                .filter(Boolean)
                .join(" · ")}
            </p>
          ) : null}
          {err?.detail ? (
            <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) text-pretty">{err.detail}</p>
          ) : null}
          {err?.hint ? (
            <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) text-pretty">
              <span className="text-(color:--chatcn-fg) font-medium">Hint:</span> {err.hint}
            </p>
          ) : null}
        </div>
      ) : null}

      {empty ? (
        <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) px-3.5 py-3">
          No rows returned. The query ran without errors and matched nothing.
        </p>
      ) : null}

      {state === "canceled" && rows.length === 0 ? (
        <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) px-3.5 py-3">
          Canceled before any rows came back.
        </p>
      ) : null}

      {hasRows ? (
        <section
          data-slot="sql-result-table"
          aria-label="Query result"
          // biome-ignore lint/a11y/noNoninteractiveTabindex: scrollable regions must be reachable by keyboard
          tabIndex={0}
          style={{ maxHeight }}
          className={cn(
            "chatcn-scroll relative overflow-auto overscroll-contain outline-none",
            "focus-visible:shadow-[inset_0_0_0_2px_var(--chatcn-accent)]",
          )}
        >
          <table
            className="text-[0.8125rem]/[1.25rem] w-full border-separate border-spacing-0"
            aria-rowcount={total + 1}
          >
            <thead>
              <tr>
                {showRowNumbers ? (
                  <th
                    scope="col"
                    className="bg-(color:--chatcn-bg-subtle) border-(color:--chatcn-border) sticky top-0 z-10 h-8 w-px border-b ps-3.5 pe-1"
                  >
                    <span className="sr-only">Row</span>
                  </th>
                ) : null}
                {columns.map((column, i) => (
                  <th
                    key={`${column.name}-${i}`}
                    scope="col"
                    className={cn(
                      "text-[0.75rem]/[1rem] text-(color:--chatcn-fg-muted) bg-(color:--chatcn-bg-subtle) border-(color:--chatcn-border) sticky top-0 z-10 h-8 border-b px-3 font-mono font-medium whitespace-nowrap",
                      column.type === "number" ? "text-end" : "text-start",
                      !showRowNumbers && i === 0 && "ps-3.5",
                      i === columns.length - 1 && "pe-3.5",
                      wide.has(i) && "w-full",
                    )}
                  >
                    {column.name}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map((row, r) => (
                <tr key={offset + r} aria-rowindex={offset + r + 2}>
                  {showRowNumbers ? (
                    <td className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) border-(color:--chatcn-border) h-8 border-b ps-3.5 pe-1 text-end font-mono tabular-nums select-none [tr:last-child>&]:border-b-0">
                      {(offset + r + 1).toLocaleString("en-US")}
                    </td>
                  ) : null}
                  {columns.map((column, c) => (
                    <td
                      key={`${column.name}-${c}`}
                      className={cn(
                        "border-(color:--chatcn-border) h-8 border-b px-3 whitespace-nowrap [tr:last-child>&]:border-b-0",
                        column.type === "number" ? "text-end font-mono tabular-nums" : "text-start",
                        column.type === "json" && "text-[0.75rem]/[1rem] font-mono",
                        !showRowNumbers && c === 0 && "ps-3.5",
                        c === columns.length - 1 && "pe-3.5",
                        wide.has(c) && "w-full max-w-0",
                      )}
                    >
                      <SqlCell
                        value={cellAt(row, c, column.name)}
                        column={column}
                        truncateAfter={truncateAfter}
                      />
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      ) : null}

      {footer ? (
        <div
          data-slot="sql-result-footer"
          className="border-(color:--chatcn-border) flex min-h-10 items-center gap-1.5 border-t py-1.5 ps-3.5 pe-2"
        >
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) min-w-0 flex-1 truncate tabular-nums">
            {paged && hasRows
              ? `Showing ${(offset + 1).toLocaleString("en-US")} to ${(offset + rows.length).toLocaleString("en-US")} of ${plural(total, "row")}`
              : truncated
                ? `Showing ${rows.length.toLocaleString("en-US")} of ${plural(total, "row")}`
                : null}
          </span>
          {paged && hasRows ? (
            <span className="flex shrink-0 items-center gap-0.5">
              <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) pe-1.5 tabular-nums">
                Page {page.toLocaleString("en-US")} of {pageCount.toLocaleString("en-US")}
              </span>
              <Button
                size="icon-sm"
                aria-label="Previous page"
                disabled={page <= 1}
                onClick={() => onPageChange(page - 1)}
                className="pointer-coarse:size-11"
              >
                <ChevronLeftIcon className="rtl:rotate-180" />
              </Button>
              <Button
                size="icon-sm"
                aria-label="Next page"
                disabled={page >= pageCount}
                onClick={() => onPageChange(page + 1)}
                className="pointer-coarse:size-11"
              >
                <ChevronRightIcon className="rtl:rotate-180" />
              </Button>
            </span>
          ) : null}
          {running && onCancel ? (
            <Button size="sm" className="pointer-coarse:h-11" onClick={onCancel}>
              <CircleStopIcon />
              Cancel query
            </Button>
          ) : null}
          {state === "error" && onRetry ? (
            <Button size="sm" className="pointer-coarse:h-11" onClick={onRetry}>
              <RotateCcwIcon />
              Retry query
            </Button>
          ) : null}
          {state === "canceled" && onRetry ? (
            <Button size="sm" className="pointer-coarse:h-11" onClick={onRetry}>
              <RotateCcwIcon />
              Run again
            </Button>
          ) : null}
        </div>
      ) : null}

      {/* Announce the outcome once, never the timer. */}
      <span aria-live="polite" className="sr-only">
        {announcement}
      </span>
    </div>
  )
}

export default SqlResult

