"use client"

import * as React from "react"
import { SqlColumn, SqlResult, SqlRow } from "@/components/ui/sql-result"

const reducedMotion = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches

interface Query {
  query: string
  columns: SqlColumn[]
  rows: SqlRow[]
  durationMs: number
}

const churnQuery = `SELECT a.name AS account, s.plan, a.region, s.canceled_at::date AS canceled_on,
       s.mrr_cents / 100.0 AS mrr_lost, e.payload ->> 'reason' AS cancel_reason
FROM subscriptions s
JOIN accounts a ON a.id = s.account_id
LEFT JOIN events e ON e.subscription_id = s.id AND e.type = 'cancel_survey'
WHERE s.canceled_at >= '2026-03-01' AND s.canceled_at < '2026-04-01'
ORDER BY mrr_lost DESC;`

